      ro: ["Cel mai înalt vârf: Thabana Ntlenyana (3.482 m).", "Sit UNESCO din anul 2000 pentru natură și cultură.", "Adăpostește peste 35.000 de picturi rupestre San.", "Se întinde pe o lungime de peste 1.000 km.", "Cascada Tugela are o înălțime totală de 948 m.", "Format prin activitate vulcanică acum 180 mil. ani."],
