      es: ["El pico más alto es el Thabana Ntlenyana con 3.482 m.", "La cadena montañosa se extiende por 1.000 km.", "Las Drakensberge son Patrimonio de la Humanidad por la UNESCO desde 2000.", "La región alberga más de 2.000 especies de plantas.", "El Parque Nacional Royal Natal es parte de la cadena.", "Las pinturas rupestres tienen hasta 3.000 años de antigüedad."],
