    description: { de: "Ein Fluss im Western Cape.", hu: "Folyó a Western Cape-ben.", ro: "Un râu în Western Cape.", en: "A river in the Western Cape." , es: "Un río en la provincia de Cabo Occidental.", pt: "Um rio na província do Cabo Ocidental.", fr: "Une rivière dans la province du Cap-Occidental."},
