      es: ["Longitud de la pared rocosa: aprox. 5 km", "Altura máxima: 1.200 m", "Altura de las Tugela Falls: 948 m", "Superficie del Parque Nacional Royal Natal: 8.000 ha", "Altura del Mount-Aux-Sources: 3.282 m", "Año del reconocimiento de la UNESCO: 2000"],
      pt: ["Comprimento da parede rochosa: aprox. 5 km", "Altura máxima: 1.200 m", "Altura das Tugela Falls: 948 m", "Área do Parque Nacional Royal Natal: 8.000 ha", "Altura do Mount-Aux-Sources: 3.282 m", "Ano do reconhecimento da UNESCO: 2000"],
      fr: ["Longueur de la paroi rocheuse : env. 5 km", "Hauteur maximale : 1 200 m", "Hauteur des Tugela Falls : 948 m", "Superficie du parc national Royal Natal : 8 000 ha", "Hauteur du Mount-Aux-Sources : 3 282 m", "Année de reconnaissance par l'UNESCO : 2000"],
