    name: { de: "Kap Agulhas", hu: "Agulhas-fok", ro: "Capul Agulhas", en: "Cape Agulhas"},
    description: { de: "Der südlichste Punkt des afrikanischen Kontinents.", hu: "Az afrikai kontinens legdélibb pontja.", ro: "Cel mai sudic punct al continentului african.", en: "The southernmost point of the African continent." , es: "El punto más austral del continente africano.", pt: "O ponto mais meridional do continente africano.", fr: "Le point le plus au sud du continent africain."},
    facts: {
      de: ["Treffpunkt von Atlantik und Indischem Ozean.", "Historischer Leuchtturm."],
      hu: ["Az Atlanti- és az Indiai-óceán találkozása.", "Történelmi világítótorony."],
      ro: ["Punctul de întâlnire al Atlanticului și Oceanului Indian.", "Far istoric."],
      en: ["Meeting point of Atlantic and Indian Ocean.", "Historic lighthouse."],
      es: ["Punto de encuentro del Atlántico y el Índico.", "Faro histórico."],
      pt: ["Ponto de encontro do Atlântico e do Índico.", "Farol histórico."],
      fr: ["Point de rencontre de l'Atlantique et de l'Indien.", "Phare historique."],
    }, image: "/poi-images/agullhas-cape-nature-v2.webp",
    descriptionAdvanced: {
      de: "Kap Agulhas ist der geografisch südlichste Punkt des afrikanischen Kontinents und markiert die offizielle Grenze zwischen dem Atlantischen und dem Indischen Ozean. Im Gegensatz zum bekannteren Kap der Guten Hoffnung ist Kap Agulhas eine eher flache, felsige Landspitze, die jedoch aufgrund ihrer nautischen Geschichte weltweit bekannt ist. Der Name stammt vom portugiesischen Wort für 'Nadeln', da die Kompassnadeln der frühen Seefahrer hier keine Abweichung zwischen geografischem und magnetischem Nordpol zeigten. Die Küste ist berüchtigt für ihre gefährlichen Unterwasserfelsen und heftigen Stürme, die im Laufe der Jahrhunderte zum Untergang von über 150 Schiffen führten. Ein markantes Wahrzeichen ist der 1848 errichtete Leuchtturm, der nach dem Vorbild des antiken Pharos von Alexandria entworfen wurde und heute ein Museum beherbergt. Die Region ist Teil des Agulhas Nationalparks, der zum Schutz der einzigartigen Fynbos-Vegetation und der fragilen Küstenökosysteme gegründet wurde. An der Mündung treffen der kalte Benguela-Strom und der warme Agulhas-Strom aufeinander, was zu einer enormen marinen Biodiversität führt. Besucher können an dem offiziellen Denkmal, das die Trennung der Ozeane markiert, ein Foto machen und die raue Schönheit dieser geschichtsträchtigen Grenze erleben.",
      hu: "Az Agulhas-fok az afrikai kontinens legdélibbi földrajzi pontja, amely hivatalos választóvonalat képez az Atlanti- és az Indiai-óceán között. A közismertebb Jóreménység fokával ellentétben az Agulhas-fok egy viszonylag lapos, sziklás kiszögellés, amely azonban hajózástörténeti szempontból világszerte kiemelkedő jelentőségű. Nevét a portugál „tűk” szóról kapta, mivel a korai felfedezők idején itt az iránytű tűje pontosan az északi irányt mutatta, mágneses elhajlás nélkül. A partvidék hírhedt a veszélyes víz alatti szikláiról és a heves viharokról, amelyek az évszázadok során több mint 150 hajó pusztulását okozták. A terület egyik legismertebb jelképe az 1848-ban épült világítótorony, amelyet az alexandriai Phárosz mintájára terveztek, és ma múzeumnak ad otthont. A régió az Agulhas Nemzeti Park része, amely az egyedülálló fynbos növényzetet és a sérülékeny parti ökoszisztémákat óvja. Itt találkozik a hideg Benguela-áramlat és a meleg Agulhas-áramlat, ami rendkívül gazdag tengeri élővilágot eredményez. A látogatók megtekinthetik az óceánok találkozását jelző hivatalos emlékművet, és felfedezhetik e történelmi jelentőségű határvidék vadregényes szépségét.",
      ro: "Capul Agulhas reprezintă cel mai sudic punct geografic al continentului african și marchează granița oficială dintre Oceanul Atlantic și Oceanul Indian. Spre deosebire de Capul Bunei Speranțe, care este mai faimos pentru peisajul său muntos, Capul Agulhas este un promontoriu stâncos și relativ plat, dar de o importanță nautică globală. Numele provine din cuvântul portughez pentru „ace”, deoarece primii navigatori au observat că în acest punct acul busolei nu prezenta nicio deviație între nordul magnetic și cel geografic. Coasta este notorie pentru rocile submerse periculoase și furtunile violente, care au provocat scufundarea a peste 150 de nave de-a lungul secolelor. Un simbol marcant este farul construit în 1848, inspirat de arhitectura farului din Alexandria, care astăzi găzduiește un muzeu dedicat istoriei maritime. Regiunea este inclusă în Parcul Național Agulhas, înființat pentru a proteja vegetația rară de tip fynbos și ecosistemele costiere fragile. Aici se întâlnesc curentul rece al Benguelei și curentul cald al Agulhas, generând o biodiversitate marină extraordinară. Vizitatorii pot vedea monumentul oficial care marchează separarea celor două oceane și pot admira frumusețea aspră a acestui punct extrem al Africii.",
      en: "Cape Agulhas is the true southernmost geographic point of the African continent and the official dividing line between the Atlantic and Indian Oceans. Unlike the more famous Cape of Good Hope, Cape Agulhas is a relatively low-lying, rocky headland, yet it holds immense global nautical and geographical significance. Its name is derived from the Portuguese word for 'needles', as early navigators discovered that compass needles showed no magnetic deviation here, pointing directly to true north. The coastline is notorious for its treacherous submerged reefs and violent storms, which have claimed over 150 shipwrecks throughout history. A prominent landmark is the Cape Agulhas Lighthouse, constructed in 1848 and modeled after the ancient Pharos of Alexandria, which now operates as a maritime museum. The surrounding region is protected within the Agulhas National Park, established to conserve the unique fynbos vegetation and fragile coastal ecosystems. The confluence of the cold Benguela Current and the warm Agulhas Current here creates a highly productive marine environment with exceptional biodiversity. Visitors can stand at the official monument marking the junction of the oceans and experience the raw beauty of this historic and geographical extremity of Africa.",
      es: "El Cabo Agulhas es el punto más austral del continente africano. Se encuentra en la provincia de Cabo Occidental, a unos 176 km al sureste de Ciudad del Cabo. El faro del Cabo Agulhas, construido en 1848, es un hito. La costa es conocida por sus olas fuertes y vientos intensos, que históricamente provocaron muchos naufragios. El Cabo Agulhas marca la frontera oficial entre el Atlántico y el Océano Índico. La región forma parte del Parque Nacional Agulhas, que protege la vegetación fynbos única. Las temperaturas del agua varían mucho entre los océanos.",
      pt: "O Cabo Agulhas é o ponto mais a sul do continente africano. Situa-se na província do Cabo Ocidental, a cerca de 176 km a sudeste da Cidade do Cabo. O farol do Cabo Agulhas, construído em 1848, é um marco. A costa é conhecida pelas suas ondas fortes e ventos intensos, que historicamente causaram muitos naufrágios. O Cabo Agulhas marca a fronteira oficial entre o Oceano Atlântico e o Oceano Índico. A região faz parte do Parque Nacional Agulhas, que protege a vegetação única de fynbos. As temperaturas da água variam muito entre os oceanos.",
      fr: "Le cap des Aiguilles est le point le plus au sud du continent africain. Il est situé dans la province du Cap-Occidental, à environ 176 km au sud-est du Cap. Le phare du cap des Aiguilles, construit en 1848, est un point de repère. La côte est connue pour ses vagues brutales et ses vents violents, qui ont historiquement causé de nombreux naufrages. Le cap des Aiguilles marque la frontière officielle entre l'océan Atlantique et l'océan Indien. La région fait partie du parc national des Aiguilles, qui protège la végétation unique du fynbos. Les températures de l'eau varient considérablement entre les océans.",
    },
