      pt: ["Coordenadas geográficas: 34°50′S 20°00′E", "Distância da Cidade do Cabo: 176 km", "Ano de construção do farol: 1848", "Altura do farol: 27 m", "Número de naufrágios na zona: mais de 150", "Área do Parque Nacional Agulhas: 56.000 ha"],
