      ro: ["Fondat în 1931 pentru a salva ultimii 11 elefanți locali.", "Găzduiește în prezent peste 600 de elefanți africani.", "Singurul parc din lume care adăpostește grupul 'Big Seven'.", "Include o rezervație marină vastă în Golful Algoa.", "Protejează cea mai mare colonie de pinguini africani din lume.", "Habitat pentru gândacul de baligă apter, specie rară."],
      en: ["Established in 1931 to protect the last 11 surviving elephants.", "Currently home to a population of over 600 African elephants.", "The only park in the world to host the 'Big Seven' wildlife.", "Includes a massive marine protected area in Algoa Bay.", "Protects the world's largest colony of African penguins.", "Provides a sanctuary for the rare flightless dung beetle."],
      es: ["Fundado en 1931 con solo 11 elefantes", "Hoy hay más de 600 elefantes en el parque", "Superficie del parque: 1.640 km²", "Punto más alto: 1.000 m sobre el nivel del mar", "Incluye 5 zonas de vegetación", "Área marina protegida: 120 km de costa"],
