      fr: ["Fondé en 1931 avec seulement 11 éléphants", "Aujourd'hui, plus de 600 éléphants dans le parc", "Superficie du parc : 1 640 km²", "Point culminant : 1 000 m au-dessus du niveau de la mer", "Comprend 5 zones de végétation", "Réserve marine : 120 km de littoral"],
