      ro: ["Desemnat ca sit Ramsar de importanță globală în 1995.", "Marchează granița naturală între Africa de Sud și Namibia.", "Transportă anual milioane de tone de sedimente în Atlantic.", "Loc important de cuibărit pentru rândunica de mare Damara.", "Cunoscut pentru cele mai mari zăcăminte aluvionare de diamante.", "Găzduiește sezonier peste 25.000 de păsări acvatice."],
      en: ["Designated as an international Ramsar wetland since 1995.", "Forms the official border between South Africa and Namibia.", "Transports millions of tons of sediment to the Atlantic annually.", "Critical breeding site for the endangered Damara tern.", "Famed for having the world's richest alluvial diamond deposits.", "Supports up to 25,000 waterbirds during peak seasons."],
      es: ["Sitio Ramsar desde 1995", "Superficie: 200 km²", "Transporte anual de sedimentos: 60 millones de toneladas", "Más de 150 especies de aves", "Marismas más grandes en la costa sur africana", "Profundidad media del agua: 2 m"],
      pt: ["Sítio Ramsar desde 1995", "Área: 200 km²", "Transporte anual de sedimentos: 60 milhões de toneladas", "Mais de 150 espécies de aves", "Maiores sapais na costa sul africana", "Profundidade média da água: 2 m"],
      fr: ["Site Ramsar depuis 1995", "Superficie : 200 km²", "Transport annuel de sédiments : 60 millions de tonnes", "Plus de 150 espèces d'oiseaux", "Plus grands marais salants de la côte sud africaine", "Profondeur moyenne de l'eau : 2 m"],
